# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 12)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        spans = [Span(9 * 60 + 5, 10 * 60 + 15)]
        self.assertEqual(
            round_spans(spans, 10), ["09:10-10:20 (1h 10m)"]
        )

    def test_several_spans_keep_order(self):
        spans = [Span(60, 120), Span(180, 240)]
        self.assertEqual(
            round_spans(spans, 30),
            ["01:00-02:00 (1h 0m)", "03:00-04:00 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)
